def evaluate(
    current_reputation: float,
    observation: dict,
    my_history: list[dict],
    round_num: int
) -> float:
    # Standing: evaluate action based on recipient's current reputation (unknown here)
    # We approximate: donate is good, not_donate is bad; but consider if recipient is bad.
    # We don't have recipient reputation, so we use observation to infer social standing.
    # Simple version: if donate, +1; if not_donate and we know recipient is bad? no info.
    # To be different: update based on action only, but with asymmetry.
    # Actually, we can only observe the donor's action. So we use the donor's action.
    if observation['action'] == 'donate':
        new_rep = current_reputation + 1.0
    else:
        new_rep = current_reputation - 1.0
    return max(-1.0, min(1.0, new_rep))

def decide(
    recipient_reputation: float,
    round_num: int,
    my_history: list[dict]
) -> bool:
    # Reciprocity: if the recipient ever donated to me in the past, donate; else not.
    for entry in my_history:
        if entry['role'] == 'recipient' and entry['partner_action'] == 'donate':
            return True
    # Also consider if I have never interacted before, use reputation threshold
    if recipient_reputation > 0.0:
        return True
    return False
